;;
; @file   script_20.asm
; @brief   Cow funeral cut scene. Started by fAreaEvents_House (slot 0) when a cow has died (event6 bit $0040, cow
;         name copied to strcNames.wCurrentCow): the player is moved to the town of the current season, an NPC prays
;         (dialog $0315) and a second NPC scolds the player (dialog $0316); the scene ends with the memorial dialog
;         $038A, a happiness penalty and the time set to hour $0F.
; @bank   $B4   (AI byte code; script id $20, slot table generated by tools/ai/aidata.py from defs/ai/scripts.json)
; @see     script_21 script_22 docs/ai/commands.md
;;



    incsrc "../../../../build/gen/ai/slots_20.asm"
 
;;
; @brief   Cow funeral sequence in the town square for the current season.
; @details Entry code: music Funeral; hour $0E; destination !AREA_TOWNSPRING, !AREA_TOWNSUMMER, !AREA_TOWNFALL,
;         !AREA_TOWNWINTER; starts 2 child scripts (slots $01, $02); dialogs $038A, $0315, $0316.
; @slot    0   (script slot index; AICMD0x09 / %AIExecute second argument)
; @callers fAreaEvents_House (A=$0000)
;;
pAIScripting0x20_Data01:
    %AICMD0x50()                                               ;B49E51
    %AICMD0x23_OrWithIndexedValue(strcFlags.daily4, $09)       ;B49E52
    %AICMD0x23_OrWithIndexedValue(strcFlags.daily3, $02)       ;B49E57
    %AICMD0x00_SetMusic($0C, $B4)                              ;B49E5C
    %AICMD0x01_UnfreezeTime()                                  ;B49E5F
    %AICMD0x03_SetHour($0E)                                    ;B49E60
    %AICMD0x05_SetTransferPosition(440, 160)                   ;B49E62
    %AICMD0x07_SetPlayerDirection(!PDIR_UP)                    ;B49E67
    %AICMD0x08_EnableAIControl()                               ;B49E69
    %AICMD0x09_StartScript($01, pAIScripting0x20_Data01_Actor01)                                   ;B49E6A
    %AICMD0x09_StartScript($02, pAIScripting0x20_Data01_Actor02)                                   ;B49E6E
    %AICMD0x15_JumpIfEquals8(nCurrentSeasonID, 0, pAIScripting0x20_Data01_SetDest_TOWNSPRING)     ;B49E72
    %AICMD0x15_JumpIfEquals8(nCurrentSeasonID, 1, pAIScripting0x20_Data01_SetDest_TOWNSUMMER)     ;B49E79
    %AICMD0x15_JumpIfEquals8(nCurrentSeasonID, 2, pAIScripting0x20_Data01_SetDest_TOWNFALL)     ;B49E80
    %AICMD0x15_JumpIfEquals8(nCurrentSeasonID, 3, pAIScripting0x20_Data01_SetDest_TOWNWINTER)     ;B49E87
; Select the destination area for the scene.
pAIScripting0x20_Data01_SetDest_TOWNSPRING:
    %AICMD0x06_SetDestinationArea(!AREA_TOWNSPRING)            ;B49E8E
    %AICMD0x12_Jump(pAIScripting0x20_Data01_FuneralSequence)                                   ;B49E90
; Select the destination area for the scene.
pAIScripting0x20_Data01_SetDest_TOWNSUMMER:
    %AICMD0x06_SetDestinationArea(!AREA_TOWNSUMMER)            ;B49E93
    %AICMD0x12_Jump(pAIScripting0x20_Data01_FuneralSequence)                                   ;B49E95
; Select the destination area for the scene.
pAIScripting0x20_Data01_SetDest_TOWNFALL:
    %AICMD0x06_SetDestinationArea(!AREA_TOWNFALL)              ;B49E98
    %AICMD0x12_Jump(pAIScripting0x20_Data01_FuneralSequence)                                   ;B49E9A
; Select the destination area for the scene.
pAIScripting0x20_Data01_SetDest_TOWNWINTER:
    %AICMD0x06_SetDestinationArea(!AREA_TOWNWINTER)            ;B49E9D
    %AICMD0x12_Jump(pAIScripting0x20_Data01_FuneralSequence)                                   ;B49E9F
; Main funeral sequence: wait for the NPCs (script flag 2), memorial dialog $038A, happiness -100, time set to hour
; $0F (nTimeState = 3).
pAIScripting0x20_Data01_FuneralSequence:
    %AICMD0x38_WaitForFadeIn()                                               ;B49EA2
    %AICMD0x0B_SetScriptFlag($00)                                            ;B49EA3
    %AICMD0x0C_WaitForScriptFlag($02)                                            ;B49EA5
    %AICMD0x19($0025, $00)                                     ;B49EA7
    %AICMD0x13_Wait(180)                                       ;B49EAB
    %AICMD0x01_UnfreezeTime()                                  ;B49EAE
    %AICMD0x24_NextHourPalette($74)                            ;B49EAF
    %AICMD0x13_Wait(180)                                       ;B49EB1
    %AICMD0x1C_ShowDialog($038A, $00)                          ;B49EB4
    %AICMD0x41_AddValue16(nPlayerHappiness, -100)              ;B49EB8
    %AICMD0x03_SetHour($0F)                                    ;B49EBE
    %AICMD0x47_SetValue8(wram80(nTimeState), 3)                           ;B49EC0
    %AICMD0x10_End()                                           ;B49EC5
; Child script (slot $01) of Data01: actor. Spawns at (408,152).
pAIScripting0x20_Data01_Actor01:
    %AICMD0x1A($0198, $0098, aAIScriptingData_L051, $02)                     ;B49EC6
; Conversation handler: dialog $0315 "Our Father in Heaven,please help his preciou...".
pAIScripting0x20_Data01_Actor01_Talk_0315:
    %AICMD0x0C_WaitForScriptFlag($00)                                            ;B49ECE
    %AICMD0x13_Wait(120)                                       ;B49ED0
    %AICMD0x1C_ShowDialog($0315, $00)                          ;B49ED3
    %AICMD0x0B_SetScriptFlag($01)                                            ;B49ED7
; Idle until the player talks to the NPC (AICMD0x1F polls A near the actor), then jump to the conversation.
pAIScripting0x20_Data01_Actor01_WaitTalk:
    %AICMD0x1F(pAIScripting0x20_Data01_Actor01_Talk_0315)                                        ;B49ED9
    %AICMD0x12_Jump(pAIScripting0x20_Data01_Actor01_WaitTalk)                                   ;B49EDC
; Child script (slot $02) of Data01: actor. Spawns at (504,144).
pAIScripting0x20_Data01_Actor02:
    %AICMD0x1A($01F8, $0090, aAIScriptingData_L053, $03)                     ;B49EDF
    %AICMD0x0C_WaitForScriptFlag($01)                                            ;B49EE7
    %AICMD0x1B($02B0, $00)                                     ;B49EE9
    %AICMD0x0D($FF, $00, $30, $01)                             ;B49EED
    %AICMD0x1B($02AB, $00)                                     ;B49EF2
    %AICMD0x13_Wait(120)                                       ;B49EF6
    %AICMD0x1C_ShowDialog($0316, $00)                          ;B49EF9
    %AICMD0x1B($02B0, $01)                                     ;B49EFD
    %AICMD0x0D($01, $00, $30, $01)                             ;B49F01
    %AICMD0x1B($02AC, $00)                                     ;B49F06
    %AICMD0x0D($00, $01, $90, $01)                             ;B49F0A
    %AICMD0x0B_SetScriptFlag($02)                                            ;B49F0F
    %AICMD0x37()                                               ;B49F11
    %AICMD0x10_End()                                           ;B49F12
